package meibasic

import scala.xml.*

object MeiXML {

  def load(xml: Elem): _root_.meibasic.mei.shared.Mei = {
    loadElement(xml) match {
      case m: _root_.meibasic.mei.shared.Mei => m
      case other => throw new IllegalArgumentException(s"Root element must be 'mei', but got ${other.getClass.getSimpleName}")
    }
  }

  def loadElement(node: Node): meibasic.Element = node match {
    case e: Elem =>
      val attributes: scala.collection.immutable.SeqMap[String, String] = scala.collection.immutable.SeqMap.from(
        e.attributes.map {
          case p: scala.xml.PrefixedAttribute => (s"${p.pre}:${p.key}", p.value.text)
          case u: scala.xml.UnprefixedAttribute => (u.key, u.value.text)
          case m => (m.key, m.value.text)
        }
      )
      val children = e.child.flatMap { n => 
        loadElement(n) match {
          case t: meibasic.Text if t.value.trim.isEmpty => None // No blank Text nodes are created
          case other => Some(other)
        }
      }.toList
      
      e.label match {
      case "accid" => _root_.meibasic.mei.shared.Accid(children, attributes)
      case "arpeg" => _root_.meibasic.mei.cmn.Arpeg(children, attributes)
      case "arranger" => _root_.meibasic.mei.shared.Arranger(children, attributes)
      case "artic" => _root_.meibasic.mei.shared.Artic(children, attributes)
