      case "barre" => _root_.meibasic.mei.stringtab.Barre(children, attributes)
      case "beam" => _root_.meibasic.mei.cmn.Beam(children, attributes)
      case "beatRpt" => _root_.meibasic.mei.cmn.BeatRpt(children, attributes)
      case "body" => _root_.meibasic.mei.shared.Body(children, attributes)
      case "breath" => _root_.meibasic.mei.cmn.Breath(children, attributes)
      case "caesura" => _root_.meibasic.mei.shared.Caesura(children, attributes)
      case "chord" => _root_.meibasic.mei.shared.Chord(children, attributes)
      case "chordDef" => _root_.meibasic.mei.harmony.ChordDef(children, attributes)
      case "chordMember" => _root_.meibasic.mei.harmony.ChordMember(children, attributes)
      case "chordTable" => _root_.meibasic.mei.harmony.ChordTable(children, attributes)
